// Reproduction using Puppeteer
// 1) Inject a performance.mark before NavigationStart
// 2) Navigate to the target page
// 3) Add additional marks/measures
// 4) Log out the User Timing entries (will include negative startTime)

const puppeteer = require('puppeteer');

;(async () => {
  const browser = await puppeteer.launch({headless: true});
  const page = await browser.newPage();

  // 1) Inject a mark in the earliest possible context (before navStart)
  await page.evaluateOnNewDocument(() => {
    performance.mark('mark_features_unveil_start');
  });

  // 2) Navigate to the page under test
  await page.goto('https://www.chromestatus.com/features', { waitUntil: 'networkidle0' });

  // 3) Add more marks/measures after load
  await page.evaluate(() => {
    performance.mark('mark_features_loaded_start');
    performance.mark('mark_features_loaded_end');
    performance.measure('features_loaded', 'mark_features_loaded_start', 'mark_features_loaded_end');
  });

  // 4) Retrieve all User Timing entries
  const entries = await page.evaluate(() => performance.getEntries());
  console.log('User Timing entries:');
  entries.forEach(e => console.log(
    `${e.entryType} "${e.name}" – startTime: ${e.startTime.toFixed(2)}ms, ` +
    (e.duration ? `duration: ${e.duration.toFixed(2)}ms` : ''))
  );

  await browser.close();
})();
